28: @implementation AppKitImpl
29: 
30: - (id) initWithObject:(AppKit*)appkit
31: {
32:     self = [super init];
33: 
34:     if (self) {
35:         m_appkit = appkit;
36:         [[[NSWorkspace sharedWorkspace] notificationCenter] addObserver:self
37:                                                            selector:@selector(didDeactivateApplicationObserver:)
38:                                                                name:NSWorkspaceDidDeactivateApplicationNotification
39:                                                              object:nil];
40: 
41:         [[[NSWorkspace sharedWorkspace] notificationCenter] addObserver:self
42:                                                             selector:@selector(userSwitchHandler:)
43:                                                                 name:NSWorkspaceSessionDidResignActiveNotification
44:                                                                 object:nil];
45: 
46:         [NSApp addObserver:self forKeyPath:@"effectiveAppearance" options:NSKeyValueObservingOptionNew context:nil];
47:     }
48:     return self;
49: }
50: 
51: //
52: // Update last active application property
53: //
54: - (void) didDeactivateApplicationObserver:(NSNotification*) notification
55: {
56:     NSDictionary* userInfo = notification.userInfo;
57:     NSRunningApplication* app = [userInfo objectForKey:NSWorkspaceApplicationKey];
58: 
59:     if (app.processIdentifier != [self ownProcessId]) {
60:         self.lastActiveApplication = app;
61:     }
62: }
63: 
64: - (void) observeValueForKeyPath:(NSString *)keyPath
65:                       ofObject:(id)object
66:                         change:(NSDictionary<NSKeyValueChangeKey,id> *)change
67:                        context:(void *)context
68: {
69:     Q_UNUSED(object)
70:     Q_UNUSED(change)
71:     Q_UNUSED(context)
72:     if ([keyPath isEqualToString:@"effectiveAppearance"]) {
