272:     if (type == XCB_KEY_PRESS) {
273:         auto* keyPressEvent = static_cast<xcb_key_press_event_t*>(message);
274:         auto modifierMask = ControlMask | ShiftMask | Mod1Mask | Mod4Mask;
275:         return triggerGlobalShortcut(keyPressEvent->detail, keyPressEvent->state & modifierMask);
