302: bool NixUtils::registerGlobalShortcut(const QString& name, Qt::Key key, Qt::KeyboardModifiers modifiers, QString* error)
303: {
304:     if (externalGlobalShortcutsConfigurator()) {
305:         return true;
306:     }
307: 
308: #ifdef WITH_X11
309:     if (!dpy) {
310:         return true;
311:     }
312: 
313:     auto keycode = XKeysymToKeycode(dpy, qtToNativeKeyCode(key));
314:     auto modifierscode = qtToNativeModifiers(modifiers);
315: 
316:     // Check if this key combo is registered to another shortcut
317:     QHashIterator<QString, QSharedPointer<globalShortcut>> i(m_globalShortcuts);
318:     while (i.hasNext()) {
319:         i.next();
320:         if (i.value()->nativeKeyCode == keycode && i.value()->nativeModifiers == modifierscode && i.key() != name) {
321:             if (error) {
322:                 *error = tr("Global shortcut already registered to %1").arg(i.key());
323:             }
324:             return false;
325:         }
326:     }
327: 
328:     unregisterGlobalShortcut(name);
329: 
330:     x11ErrorOccurred = false;
331:     auto prevHandler = XSetErrorHandler(x11ErrorHandler);
332: 
333:     XGrabKey(dpy, keycode, modifierscode, rootWindow, True, GrabModeAsync, GrabModeAsync);
334:     XGrabKey(dpy, keycode, modifierscode | Mod2Mask, rootWindow, True, GrabModeAsync, GrabModeAsync);
335:     XGrabKey(dpy, keycode, modifierscode | LockMask, rootWindow, True, GrabModeAsync, GrabModeAsync);
336:     XGrabKey(dpy, keycode, modifierscode | Mod2Mask | LockMask, rootWindow, True, GrabModeAsync, GrabModeAsync);
337: 
338:     XSync(dpy, False);
339:     XSetErrorHandler(prevHandler);
340: 
341:     if (x11ErrorOccurred) {
342:         x11ErrorOccurred = false;
343:         if (error) {
344:             *error = tr("Could not register global shortcut");
345:         }
346:         return false;
347:     }
348: 
349:     auto gs = QSharedPointer<globalShortcut>::create();
350:     gs->nativeKeyCode = keycode;
351:     gs->nativeModifiers = modifierscode;
352:     m_globalShortcuts.insert(name, gs);
353: #else
354:     Q_UNUSED(name)
355:     Q_UNUSED(key)
356:     Q_UNUSED(modifiers)
357:     Q_UNUSED(error)
358: #endif
359:     return true;
360: }
361: 
362: bool NixUtils::unregisterGlobalShortcut(const QString& name)
363: {
364:     if (externalGlobalShortcutsConfigurator()) {
365:         return true;
366:     }
367: 
368: #ifdef WITH_X11
369:     if (!m_globalShortcuts.contains(name)) {
370:         return false;
371:     }
372: 
373:     auto gs = m_globalShortcuts.value(name);
374:     XUngrabKey(dpy, gs->nativeKeyCode, gs->nativeModifiers, rootWindow);
375:     XUngrabKey(dpy, gs->nativeKeyCode, gs->nativeModifiers | Mod2Mask, rootWindow);
376:     XUngrabKey(dpy, gs->nativeKeyCode, gs->nativeModifiers | LockMask, rootWindow);
377:     XUngrabKey(dpy, gs->nativeKeyCode, gs->nativeModifiers | Mod2Mask | LockMask, rootWindow);
378: 
379:     m_globalShortcuts.remove(name);
380: #else
381:     Q_UNUSED(name)
382: #endif
383:     return true;
384: }
