405: {
406:     // The remote desktop portal tracks whether KeePassXC owns the selection, so
407:     // NixUtils does not need the copied text to decide whether clearing is safe.
408:     Q_UNUSED(text)
409: 
410:     if (!autoType()->isAvailable() || !autoType()->usesDesktopPortal()) {
411:         return false;
412:     }
413: 
414:     auto* portal = m_remoteDesktopPortal;
415:     if (portal && autoType()->isAvailable() && config()->get(Config::AutoTypeDesktopPortalUseClipboard).toBool()
416:         && portal->isClipboardAvailable() && portal->hasSession()) {
417:         if (portal->clearClipboardText()) {
418:             return true;
419:         }
420: 
421:         qWarning("Failed to clear clipboard text via remote desktop portal, falling back to standard clipboard");
422:         return false;
423:     }
424: 
425:     auto* clipboard = QApplication::clipboard();
426:     auto hasClipboardData = clipboard && clipboard->mimeData(QClipboard::Clipboard)
427:                             && !clipboard->mimeData(QClipboard::Clipboard)->formats().isEmpty();
428:     auto hasSelectionData = clipboard && clipboard->supportsSelection() && clipboard->mimeData(QClipboard::Selection)
429:                             && !clipboard->mimeData(QClipboard::Selection)->formats().isEmpty();
430:     if (hasClipboardData || hasSelectionData) {
431:         return false;
432:     }
433: 
434:     // Gnome Wayland doesn't let apps modify the clipboard when not in focus, so force clear.
435:     return QProcess::startDetached(QStringLiteral("wl-copy"), {QStringLiteral("-c")});
