458: quint64 NixUtils::getProcessStartTime() const
459: {
460:     QString processStatPath = QString("/proc/%1/stat").arg(QCoreApplication::applicationPid());
461:     QFile processStatFile(processStatPath);
462: 
463:     if (!processStatFile.open(QIODevice::ReadOnly | QIODevice::Text)) {
464:         qDebug() << "nixutils: failed to open " << processStatPath;
465:         return 0;
466:     }
467: 
468:     QTextStream processStatStream(&processStatFile);
469:     QString processStatInfo = processStatStream.readLine();
470:     processStatFile.close();
471: 
472:     auto startIndex = processStatInfo.lastIndexOf(')');
473:     if (startIndex != -1) {
474:         auto tokens = QStringView{processStatInfo}.mid(startIndex + 2).split(' ');
475:         if (tokens.size() >= 20) {
476:             bool ok;
477:             auto time = tokens[19].toULongLong(&ok);
478:             if (!ok) {
479:                 qDebug() << "nixutils: failed to convert " << tokens[19] << " to an integer in " << processStatPath;
480:                 return 0;
481:             }
482:             return time;
483:         }
484:         qDebug() << "nixutils: failed to find at least 20 values in " << processStatPath;
485:         return 0;
486:     }
487: 
488:     qDebug() << "nixutils: failed to find ')' in " << processStatPath;
489:     return 0;
